import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/browser/cookie-request-flow.svg",i="/study/images/browser/cookie-session-lifetime.svg",k=JSON.parse('{"title":"Cookieとセッション — 要求への付与とサーバー側の寿命","description":"","frontmatter":{"title":"Cookieとセッション — 要求への付与とサーバー側の寿命","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"Set-Cookieを受け取ってからCookieが次の要求に付くまでを説明する。属性とcredentialsの条件、セッションIDの照合、ブラウザとサーバーそれぞれの期限を整理する。","aliases":["Cookie","HTTP cookie","Set-Cookie","cookie jar","host-only","Domain","Path","Expires","Max-Age","Secure","HttpOnly","SameSite","credentials","セッション","セッションID","session fixation","CSRF","XSS"],"verification":"RFC 6265、IETFの改訂草案、WHATWG標準と照合（2026-11-05）"}},"headers":[],"relativePath":"browser/cookies-and-sessions.md","filePath":"browser/cookies-and-sessions.md"}'),d={name:"browser/cookies-and-sessions.md"};function c(h,e,n,l,p,f){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="cookieとセッション-—-要求への付与とサーバー側の寿命" tabindex="-1">Cookieとセッション — 要求への付与とサーバー側の寿命 <a class="header-anchor" href="#cookieとセッション-—-要求への付与とサーバー側の寿命" aria-label="Permalink to &quot;Cookieとセッション — 要求への付与とサーバー側の寿命&quot;">​</a></h1><p><strong>Cookie</strong>は、ブラウザが名前と値を保存し、条件が合うHTTP要求に付ける仕組みです。たとえば<strong>セッションID</strong>をCookieに入れると、サーバーは次の要求でそのIDを受け取り、ログイン情報や期限などの状態を照合できます。ブラウザでCookieが残る期間と、サーバーがIDを有効と判断する期間は別々に決まります。<a href="https://www.rfc-editor.org/rfc/rfc6265.html#section-3.1" target="_blank" rel="noreferrer">RFC 6265の例</a>、<a href="https://pages.nist.gov/800-63-4/sp800-63b/session/" target="_blank" rel="noreferrer">NISTのセッション管理</a></p><h2 id="応答で設定し、次の要求で送る" tabindex="-1">応答で設定し、次の要求で送る <a class="header-anchor" href="#応答で設定し、次の要求で送る" aria-label="Permalink to &quot;応答で設定し、次の要求で送る&quot;">​</a></h2><p>たとえば <code>https://app.example.com/study/</code> の応答で、サーバーが次のヘッダーを返します。</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Set-Cookie</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_theme=dark; Path=/study/; Max-Age=600; Secure; SameSite=Lax</span></span></code></pre></div><p>ブラウザはこの指示を検査し、受け入れたCookieを属性と一緒に保存します。以後、同じホストの <code>/study/chapter.html</code> を同一サイトの文脈でHTTPS取得するとき、保存期限などの条件を満たせば次のように送ります。要求に戻すのは名前と値です。サーバーは受信した <code>Cookie</code> ヘッダーだけから、そのCookieの <code>Max-Age</code> や <code>Path</code> を判定できません。<a href="https://www.rfc-editor.org/rfc/rfc6265.html#section-4.2.2" target="_blank" rel="noreferrer">RFC 6265のCookieヘッダー</a></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cookie</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> study_theme=dark</span></span></code></pre></div><p>ブラウザ上の <code>fetch()</code> では、呼び出し元のコードが <code>Cookie</code> 要求ヘッダーを直接指定できません。<code>Set-Cookie</code> 応答ヘッダーも <code>response.headers</code> には公開されません。ブラウザがヘッダーを処理した結果は、開発者ツールで要求・応答と保存内容を分けて確認できます。JavaScriptから <code>document.cookie</code> で取得できるのは、現在の文書から利用できるCookieのうち、<code>HttpOnly</code> が付いていないものです。<a href="https://fetch.spec.whatwg.org/#forbidden-request-header" target="_blank" rel="noreferrer">WHATWG Fetchのヘッダー規則</a>、<a href="https://fetch.spec.whatwg.org/#forbidden-response-header-name" target="_blank" rel="noreferrer">応答ヘッダーの制限</a>、<a href="https://html.spec.whatwg.org/multipage/dom.html#dom-document-cookie" target="_blank" rel="noreferrer">WHATWG HTMLのdocument.cookie</a></p><figure class="study-figure"><img src="'+s+'" alt="HTTPS応答のSet-Cookieを受けたブラウザが値と属性を保存し、次の要求の送信先や期限などを確認して、条件が合うとCookieヘッダーに名前と値を付ける。例のPathではstudy配下の要求に付き、assets配下の要求には付かない。" width="760" height="1180" loading="lazy"><figcaption>保存するときに使う属性と、サーバーへ戻す名前と値を分けます。<a href="/study/images/browser/cookie-request-flow.svg" target="_blank" rel="noopener noreferrer">Cookieが要求に付く流れを拡大</a></figcaption></figure><h2 id="ブラウザが保存・送信の判断に使う属性" tabindex="-1">ブラウザが保存・送信の判断に使う属性 <a class="header-anchor" href="#ブラウザが保存・送信の判断に使う属性" aria-label="Permalink to &quot;ブラウザが保存・送信の判断に使う属性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>判断する条件</th></tr></thead><tbody><tr><td><code>Domain</code></td><td>省略すると <strong>host-only</strong> になり、設定元と同じホストが対象。許される親ドメインを指定すると、そのドメインと配下のサブドメインが対象になる。無関係なドメインは指定できない。</td></tr><tr><td><code>Path</code></td><td>要求先URLのパスが範囲に入るか。たとえば <code>/study/</code> は <code>/study/a.html</code> に一致し、<code>/study-other/a.html</code> には一致しない。</td></tr><tr><td><code>Expires</code> / <code>Max-Age</code></td><td><code>Expires</code> は期限日時、<code>Max-Age</code> は受理からの秒数。両方に有効な値があると <code>Max-Age</code> が優先される。</td></tr><tr><td><code>Secure</code></td><td>ブラウザが安全とみなす通信経路に限定する。一般のWeb配信ではHTTPSを使う。</td></tr><tr><td><code>HttpOnly</code></td><td><code>document.cookie</code> などから値を参照できなくする。他の条件を満たすHTTP要求には付く。</td></tr><tr><td><code>SameSite</code></td><td>要求の文脈が同一サイトかどうかを使って、送信や一部の保存を制限する。</td></tr></tbody></table><p>Cookieのホスト照合にはポートを使いません。同じホストの別ポートは別オリジンでも、Cookieの候補になり得ます。<code>Path</code> で決まるのはCookieを送る範囲などです。同じオリジンの別パスのページ同士ではDOMへアクセスできるため、パスに機密情報の隔離を任せられません。同じ名前でもパスやドメインの異なるCookieは共存でき、サーバーが複数を受け取る場合があります。<a href="https://www.rfc-editor.org/rfc/rfc6265.html#section-4" target="_blank" rel="noreferrer">RFC 6265の属性とヘッダーの意味</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-8.5" target="_blank" rel="noreferrer">Cookieの分離の限界を整理したIETF改訂草案 §8.5</a></p><p><code>Expires</code> と <code>Max-Age</code> を省略したものは、ブラウザが定義するセッションの終了までの <strong>セッションCookie</strong> です。セッション復元の仕方はブラウザに依存するため、タブやブラウザを閉じる操作だけでアプリのログアウトを判断できません。期限付きのCookieも、ユーザーによる削除、保存上限、ブラウザの方針などで先に消える場合があります。<a href="https://www.rfc-editor.org/rfc/rfc6265.html#section-5.3" target="_blank" rel="noreferrer">RFC 6265の保存モデル</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#limits-of-logout-on-browser-close" target="_blank" rel="noreferrer">OWASPのブラウザ終了とログアウト</a></p><p>削除するときは対象と同じ名前、<code>Domain</code> の指定有無と値、<code>Path</code> で、期限が切れたCookieを設定します。例の <code>study_theme</code> なら、同じホストのHTTPS応答から <code>Set-Cookie: study_theme=; Path=/study/; Max-Age=0; Secure; SameSite=Lax</code> を返します。別のパスに同じ名前があれば、そのCookieは別に扱います。<a href="https://www.rfc-editor.org/rfc/rfc6265.html#section-3.1" target="_blank" rel="noreferrer">RFC 6265の削除例</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-5.7" target="_blank" rel="noreferrer">IETF改訂草案の保存モデル</a></p><h2 id="samesiteと、別オリジンへのfetch" tabindex="-1">SameSiteと、別オリジンへのfetch <a class="header-anchor" href="#samesiteと、別オリジンへのfetch" aria-label="Permalink to &quot;SameSiteと、別オリジンへのfetch&quot;">​</a></h2><p>HTTP(S)のオリジンはスキーム・ホスト・ポートで区別します。一方、通常のWebサイト同士では、スキームと登録可能ドメインが一致するかがサイト比較の基準です。たとえば <code>https://app.example.com</code> と <code>https://api.example.com</code> は別オリジンでも同一サイトです。埋め込みでは祖先の文書もCookieのサイト判定に関わります。<a href="https://html.spec.whatwg.org/multipage/browsers.html#sites" target="_blank" rel="noreferrer">WHATWG HTMLのSites</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-5.2" target="_blank" rel="noreferrer">IETF改訂草案のSame-site判定</a></p><table tabindex="0"><thead><tr><th>明示した <code>SameSite</code></th><th>送信の判断</th></tr></thead><tbody><tr><td><code>Strict</code></td><td>同一サイトの文脈に限る。別サイトのリンクをたどって開く最初の要求にも付かない。</td></tr><tr><td><code>Lax</code></td><td>同一サイトに加え、別サイトからでもトップレベルの移動でGETなどのsafeメソッドを使う場合は候補になる。</td></tr><tr><td><code>None</code></td><td>別サイトにも送信できる設定。保存時に <code>Secure</code> が必要で、ブラウザのCookie制限も適用される。</td></tr></tbody></table><p>属性の省略にはブラウザの既定規則が適用されます。互換動作によって作成直後のCookieに追加の例外を設ける場合があり、明示的な <code>Lax</code> と常に同じ結果になるとは限りません。属性の値はクロスサイトのサブリソース応答などから設定できるかにも影響します。<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-4.1.2.7" target="_blank" rel="noreferrer">IETF改訂草案のSameSite属性</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-5.7" target="_blank" rel="noreferrer">保存モデル</a></p><p><code>fetch()</code> の <code>credentials: &quot;same-origin&quot;</code> は既定値で、同一オリジンに限って資格情報を扱います。<code>&quot;omit&quot;</code> ではCookieを送らず、応答の <code>Set-Cookie</code> も無視します。<code>&quot;include&quot;</code> は別オリジンでも資格情報を扱う指定ですが、ブラウザは宛先に合うCookieを選び、その <code>SameSite</code> やプライバシー設定も適用します。<a href="https://fetch.spec.whatwg.org/#concept-request-credentials-mode" target="_blank" rel="noreferrer">WHATWG Fetchのcredentials mode</a></p><p>たとえば <code>https://app.example.com</code> のコードが <code>https://api.example.com/profile</code> を取得するとします。APIのホスト用に保存済みのCookieを送るには、<code>credentials: &quot;include&quot;</code> とCookieの送信条件が関わります。取得した応答をコードが読むには、API側の <code>Access-Control-Allow-Origin: https://app.example.com</code> と <code>Access-Control-Allow-Credentials: true</code> が関わります。CORS検査で応答がコードに公開されなくても、本要求が送られていればサーバー処理やブラウザによる <code>Set-Cookie</code> の処理が起き得ます。<a href="https://fetch.spec.whatwg.org/#cors-protocol-examples" target="_blank" rel="noreferrer">WHATWG Fetchの資格情報付きCORS例</a>、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><h2 id="セッションidを使って、サーバーが状態を引く" tabindex="-1">セッションIDを使って、サーバーが状態を引く <a class="header-anchor" href="#セッションidを使って、サーバーが状態を引く" aria-label="Permalink to &quot;セッションIDを使って、サーバーが状態を引く&quot;">​</a></h2><p>サーバー側に状態を持つ方式では、認証に成功したときなどにサーバーが推測しにくいランダムなIDを発行し、IDに対応する利用者・権限・期限を保存します。ブラウザのCookieに入れるのはIDです。次の要求では、サーバーが受け取ったIDを状態と照合し、その操作の権限を確認します。有効なIDを知る相手が本人として扱われる構成では、IDの漏えいを認証情報の漏えいとして扱います。<a href="https://pages.nist.gov/800-63-4/sp800-63b/session/" target="_blank" rel="noreferrer">NISTのセッション管理</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#session-id-content-or-value" target="_blank" rel="noreferrer">OWASPのセッションIDの値</a></p><p>ログインや権限の変化ではIDを更新し、古いIDを無効化します。認証前に使っていたIDをそのまま使うと、攻撃者があらかじめ知っているIDを利用者に使わせる <strong>セッション固定攻撃</strong> が成り立ち得ます。ログアウトではサーバー側でIDを失効させ、応答でブラウザ側のCookieも期限切れにします。無操作時間や開始からの経過時間による期限もサーバーで判定できます。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#renew-the-session-id-after-any-privilege-level-change" target="_blank" rel="noreferrer">OWASPの権限変更時のID更新</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#session-expiration" target="_blank" rel="noreferrer">OWASPのセッションの期限</a></p><figure class="study-figure"><img src="'+i+'" alt="ブラウザはCookieにIDを持ち、サーバーは同じIDに対応する利用者、権限、期限を記録する。Cookieが消えた場合とサーバーでIDが失効した場合では、次の要求で失敗する箇所が異なる。ログアウト時は両方を処理する。" width="760" height="1150" loading="lazy"><figcaption>Cookieの有無と、サーバーがそのIDを受理するかを別々に観察します。<a href="/study/images/browser/cookie-session-lifetime.svg" target="_blank" rel="noopener noreferrer">セッションの寿命を拡大</a></figcaption></figure><p><strong>セッションCookie</strong>という呼び名はブラウザ側の保持方式を指し、<strong>セッションID</strong>はサーバー側で状態を探す手掛かりです。セッションIDを期限付きCookieに入れる構成もあります。<code>sessionStorage</code> はタブなどのページセッションに結び付く保存APIで、値がHTTP要求へ自動で付くことはありません。<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a></p><h2 id="httponlyとsamesiteが守る範囲" tabindex="-1">HttpOnlyとSameSiteが守る範囲 <a class="header-anchor" href="#httponlyとsamesiteが守る範囲" aria-label="Permalink to &quot;HttpOnlyとSameSiteが守る範囲&quot;">​</a></h2><p><strong>XSS</strong> により攻撃者のスクリプトがページ内で実行されると、<code>HttpOnly</code> でセッションCookieの直接読取りを抑えられても、そのページから送られた要求にCookieが付くことがあります。データがHTMLやコードに変わる箇所と、実行を制限する仕組みは次の章で扱います。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html#httponly-attribute" target="_blank" rel="noreferrer">OWASPのHttpOnly解説</a>、<a href="/study/browser/xss-and-csp.html">XSSとCSP</a></p><p><strong>CSRF</strong> では、別のページから利用者のブラウザに要求を送らせ、そこに付くCookieを利用して状態変更を起こそうとします。<code>SameSite</code> はCookieの送信範囲を絞ります。要求を受け取ったアプリが送信元やトークンを照合する手順は、次の章で扱います。<a href="/study/browser/csrf-and-request-validation.html">CSRFとリクエスト検証</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>公開版では、教材フォルダ用と子ディレクトリ用に短い期限の固定Cookieを設定し、親ページと子ページで見える名前を比べます。ローカル版では、サーバーの <code>Set-Cookie</code>、続く要求の <code>Cookie</code>、<code>HttpOnly</code> の有無による見え方、サーバー側のセッション失効を観察します。<a href="/study/practice/browser/cookie-session-observation.html">Cookieとセッションを観察する</a></p>',30)])])}const m=t(d,[["render",c]]);export{k as __pageData,m as default};
